466	func appendUnique(existing []string, values ...string) []string {
467		if len(values) == 0 {
468			return existing
469		}
470	
471		seen := make(map[string]struct{}, len(existing)+len(values))
472		for _, value := range existing {
473			seen[value] = struct{}{}
474		}
475		for _, value := range values {
476			if _, ok := seen[value]; ok {
477				continue
478			}
479			seen[value] = struct{}{}
480			existing = append(existing, value)
481		}
482	
483		return existing
484	}
