20	// cellCoreClient is the control-plane surface the cell-target resolver needs.
21	// An interface (with a swappable constructor) so the resolver is unit-testable
22	// against a fake control plane; *coreapi.Client satisfies it.
23	type cellCoreClient interface {
24		GetRepo(ctx context.Context, params coreapi.GetRepoParams) (*coreapi.Repo, error)
25		ListClusters(ctx context.Context) (*coreapi.ListClustersOutputBody, error)
26		ListMirrors(ctx context.Context, params coreapi.ListMirrorsParams) (*coreapi.ListMirrorsOutputBody, error)
27	}
28	
29	// newCellCoreClient builds the control-plane client used for cell resolution.
30	// Swapped in tests.
31	var newCellCoreClient = func() (cellCoreClient, error) { return coreapi.New() }
32	
33	// resolveRepoCellTarget resolves the entire-api cell that HOSTS the given
34	// repo, plus that cell's jurisdiction, so a repo-scoped call (experts today)
35	// reaches the region that owns the repo — mirroring how the entire.io BFF
36	// selects a cell per repo (resolve-cluster-host.ts / repos-stream.ts) rather
37	// than using the caller's home cell.
38	//
39	// It is deliberately best-effort: ANY failure (not logged in, control-plane
40	// error or timeout, unknown/ambiguous placement, missing apiUrl) returns nil,
41	// and the auth-layer client falls back to home-jurisdiction routing. That
42	// fallback is exactly the previous behaviour, so this can never regress the
43	// common same-region case (where the repo's jurisdiction equals the caller's
44	// home). A short deadline keeps a slow control plane from stalling the command.
45	//
46	// Placement source:
47	//   - ulid form: coreapi.GetRepo(ulid) -> Repo.ClusterHost;
48	//   - owner/repo form: coreapi mirrors filtered to this repo -> ClusterHost.
49	//
50	// The cluster host is then mapped to a cell apiUrl + jurisdiction via the
51	// coreapi cluster catalog (ListClusters), the authoritative source for a
52	// jurisdiction's cell URL.
53	func resolveRepoCellTarget(ctx context.Context, fullName, ulid string) *auth.CellTarget {
54		ctx, cancel := context.WithTimeout(ctx, cellResolveTimeout)
55		defer cancel()
56	
57		c, err := newCellCoreClient()
58		if err != nil {
59			logging.Debug(ctx, "cell target: core client unavailable, using home-jurisdiction routing", "error", err.Error())
60			return nil
61		}
62	
63		clusterHost, ok := resolveRepoClusterHost(ctx, c, fullName, ulid)
64		if !ok || clusterHost == "" {
65			return nil
66		}
67	
68		clusters, err := c.ListClusters(ctx)
69		if err != nil {
70			logging.Debug(ctx, "cell target: list clusters failed, using home-jurisdiction routing", "error", err.Error())
71			return nil
72		}
73		cluster, ok := matchClusterByHost(clusters.Clusters, clusterHost)
74		if !ok {
75			logging.Debug(ctx, "cell target: no cluster matched repo host, using home-jurisdiction routing", "cluster_host", clusterHost)
76			return nil
77		}
78		apiURL := strings.TrimRight(strings.TrimSpace(cluster.ApiUrl.Or("")), "/")
79		// DNS is case-insensitive; normalise the catalog jurisdiction so a
80		// non-lowercase value still passes the auth layer's strict label check
81		// instead of hard-failing the target path.
82		jurisdiction := strings.ToLower(strings.TrimSpace(cluster.Jurisdiction))
83		if apiURL == "" || jurisdiction == "" {
84			logging.Debug(ctx, "cell target: matched cluster missing apiUrl/jurisdiction, using home-jurisdiction routing", "cluster_host", clusterHost)
85			return nil
86		}
87		return &auth.CellTarget{BaseURL: apiURL, Jurisdiction: jurisdiction}
88	}
89	
90	// resolveRepoClusterHost finds the public cluster host that owns the repo. It
91	// returns ok=false to signal "fall back to home-jurisdiction routing" for every
92	// unresolved or ambiguous case, never an error.
93	func resolveRepoClusterHost(ctx context.Context, c cellCoreClient, fullName, ulid string) (string, bool) {
94		if strings.TrimSpace(ulid) != "" {
95			repo, err := c.GetRepo(ctx, coreapi.GetRepoParams{RepoId: ulid})
96			if err != nil {
97				logging.Debug(ctx, "cell target: GetRepo failed, using home-jurisdiction routing", "error", err.Error())
98				return "", false
99			}
100			return strings.TrimSpace(repo.ClusterHost.Or("")), true
101		}
102	
103		owner, repo, ok := strings.Cut(strings.TrimSpace(fullName), "/")
104		if !ok || owner == "" || repo == "" {
105			return "", false
106		}
107		mirrors, err := listMirrorsForRepo(ctx, c, mirrorCloneProviderGitHub, strings.ToLower(owner), strings.ToLower(repo))
108		if err != nil {
109			logging.Debug(ctx, "cell target: list mirrors failed, using home-jurisdiction routing", "error", err.Error())
110			return "", false
111		}
112		hosts := distinctActiveClusterHosts(mirrors)
113		if len(hosts) != 1 {
114			// Zero placements (not mirrored / unknown) or multiple regions
115			// (ambiguous which cell holds the repo-scoped data): fall back rather than
116			// guess a region.
117			if len(hosts) > 1 {
118				logging.Debug(ctx, "cell target: repo mirrored in multiple regions, using home-jurisdiction routing", "count", len(hosts))
119			}
120			return "", false
121		}
122		return hosts[0], true
123	}
124	
125	// isActiveMirror reports whether a mirror placement can currently serve the
126	// repo: not archived, and not in a failed/suspended clone state. An unset status
127	// is treated as active (older data). Shared by every caller that must ignore
128	// placements a cell can't answer for.
129	func isActiveMirror(m coreapi.Mirror) bool {
130		if m.IsArchived.Or(false) {
131			return false
132		}
133		st := m.Status.Or(coreapi.MirrorStatusReady)
134		return st != coreapi.MirrorStatusFailed && st != coreapi.MirrorStatusSuspended
135	}
136	
137	// distinctActiveClusterHosts returns the set of cluster hosts a repo is actively
138	// serviced on: excluding archived placements and unhealthy ones (failed /
139	// suspended clone status), since those cells can't answer for the repo.
140	// A failed/suspended placement must neither manufacture false cross-region
141	// ambiguity nor become a sole "active" host. Case-folded to match DNS
142	// semantics; order is unimportant (callers only use a single-member set).
143	func distinctActiveClusterHosts(mirrors []coreapi.Mirror) []string {
144		seen := make(map[string]string, len(mirrors))
145		for _, m := range mirrors {
146			if !isActiveMirror(m) {
147				continue
148			}
149			host := strings.TrimSpace(m.ClusterHost)
150			if host == "" {
151				continue
152			}
153			key := strings.ToLower(host)
154			if _, ok := seen[key]; !ok {
155				seen[key] = host
156			}
157		}
158		out := make([]string, 0, len(seen))
159		for _, host := range seen {
160			out = append(out, host)
161		}
162		return out
163	}
164	
165	// matchClusterByHost finds the catalog cluster whose public host equals
166	// clusterHost (case-insensitive). The cluster's apiUrl + jurisdiction are the
167	// authoritative cell coordinates.
168	func matchClusterByHost(clusters []coreapi.Cluster, clusterHost string) (coreapi.Cluster, bool) {
169		want := strings.ToLower(strings.TrimSpace(clusterHost))
170		if want == "" {
171			return coreapi.Cluster{}, false
172		}
173		for _, cl := range clusters {
174			host, err := hostFromPublicURL(cl.PublicUrl)
175			if err != nil {
176				continue
177			}
178			if strings.EqualFold(strings.TrimSpace(host), want) {
179				return cl, true
180			}
181		}
182		return coreapi.Cluster{}, false
183	}
