/** Resolve a jurisdictional bearer token for entire-api SpiceDB authz.
 *
 * Session-cookie callers (browser): login JWT → RFC 8693 exchange for a
 * jurisdictional identity token whose aud matches the cell's JWT_AUDIENCE.
 * Bearer callers (CLI): assumed to already carry a jurisdictional token.
 *
 * Shared by code-search (peregrine) and semantic search (entire-search) — both
 * proxy through the entire-api gateway and require the same jurisdictional token.
 *
 * `opts.loginJwt` lets a caller that already resolved the session's login JWT
 * reuse it, avoiding a duplicate `getValidLoginJwt` round-trip when the same
 * request also needs the login JWT for something else (e.g. slug → ULID
 * resolution). Ignored on the bearer/CLI path. */
export async function resolveSearchBearerToken(
  c: {
    req: { header: (name: string) => string | undefined }
    env: Env
  },
  opts?: { loginJwt?: string },
): Promise<string | undefined> {
  // CLI path: bearer token is already a jurisdictional resource token.
  const inboundAuth = c.req.header("Authorization")
  if (inboundAuth?.startsWith("Bearer ")) {
    return inboundAuth.slice("Bearer ".length)
  }

  // Browser path: exchange session's login JWT for a jurisdictional token.
  const sessionToken = getCookie(c as any, "session")
  if (
    !sessionToken ||
    !c.env.ENCRYPTION_KEY ||
    !c.env.ENTIRE_CORE_BASE_URL ||
    !c.env.ENTIRE_CORE_CLIENT_ID ||
    !c.env.ENTIRE_CORE_CLIENT_SECRET ||
    !c.env.ENTIRE_API_AUDIENCE_TEMPLATE
  ) {
    return undefined
  }

  // Derive jurisdiction from the home core URL — the first subdomain of
  // e.g. "https://us.auth.entire.io" is "us". Matches the
  // ENTIRE_CORE_BASE_URL_TEMPLATE pattern: https://{jurisdiction}.auth.{domain}
  const jurisdiction = new URL(c.env.ENTIRE_CORE_BASE_URL).hostname.split(".")[0]

  // Login JWT refresh uses the HOME core (ENTIRE_CORE_BASE_URL) — it's
  // the issuer that signed the login token.
  const homeCfg = {
    coreBaseUrl: c.env.ENTIRE_CORE_BASE_URL,
    clientId: c.env.ENTIRE_CORE_CLIENT_ID,
    clientSecret: c.env.ENTIRE_CORE_CLIENT_SECRET,
  }

  // Reuse a pre-resolved login JWT when the caller supplied one; otherwise
  // resolve it here from the session token.
  let loginJwt = opts?.loginJwt
  if (!loginJwt) {
    const loginJwtResult = await getValidLoginJwt(
      { kv: c.env.ENTIRE_CACHE, secret: c.env.ENCRYPTION_KEY, cfg: homeCfg },
      sessionToken,
    )
    if (loginJwtResult.kind !== "jwt") return undefined
    loginJwt = loginJwtResult.jwt
  }

  // Jurisdictional token exchange targets the REGIONAL core (COR-666):
  // a cell only trusts tokens signed by its own region's core.
  const issuer = buildCoreBaseUrl(
    c.env.ENTIRE_CORE_BASE_URL_TEMPLATE,
    jurisdiction,
    c.env.ENTIRE_CORE_BASE_URL,
  )
  const audience = buildAudience(c.env.ENTIRE_API_AUDIENCE_TEMPLATE, jurisdiction)
